#include <stdio.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

int print_titles(const char *path) {
  xmlDocPtr doc = xmlReadFile(path, NULL, XML_PARSE_NONET);
  if (doc == NULL) return -1;
  xmlNodePtr root = xmlDocGetRootElement(doc);
  for (xmlNodePtr n = root->children; n != NULL; n = n->next) {
    if (n->type == XML_ELEMENT_NODE && xmlStrEqual(n->name, BAD_CAST "title")) {
      printf("%s\n", (const char *)xmlNodeGetContent(n));
    }
  }
  xmlFreeDoc(doc);
  return 0;
}

