#include <stdio.h>
#include <libxml/parser.h>
#include <libxml/xpath.h>

int print_nodes(const char *path, const char *expr) {
  xmlDocPtr doc = xmlReadFile(path, NULL, XML_PARSE_NONET);
  if (doc == NULL) return -1;
  xmlXPathContextPtr ctx = xmlXPathNewContext(doc);
  if (ctx == NULL) {
    xmlFreeDoc(doc);
    return -1;
  }
  xmlXPathObjectPtr obj = xmlXPathEvalExpression(BAD_CAST expr, ctx);
  if (obj == NULL) {
    xmlXPathFreeContext(ctx);
    xmlFreeDoc(doc);
    return -1;
  }
  xmlNodeSetPtr nodes = obj->nodesetval;
  for (int i = 0; i < nodes->nodeNr; i++) {
    xmlChar *text = xmlNodeGetContent(nodes->nodeTab[i]);
    if (text == NULL) continue;
    printf("%s\n", (const char *)text);
    xmlFree(text);
  }
  xmlXPathFreeObject(obj);
  xmlXPathFreeContext(ctx);
  xmlFreeDoc(doc);
  return 0;
}

if (obj->type != XPATH_NODESET) {
  xmlXPathFreeObject(obj);
  xmlXPathFreeContext(ctx);
  xmlFreeDoc(doc);
  return -1;
}
xmlNodeSetPtr nodes = obj->nodesetval;
int count = xmlXPathNodeSetGetLength(nodes);
for (int i = 0; i < count; i++) {
  xmlChar *text = xmlNodeGetContent(xmlXPathNodeSetItem(nodes, i));
  if (text == NULL) continue;
  printf("%s\n", (const char *)text);
  xmlFree(text);
}
